/**
 * 单元测试: hooks.ts — hooks 单入口（protect-files / record-files / static-check）
 *
 * 覆盖范围:
 * - 既有 AC-1~AC-13（protect-files / static-check 各组，保持不变）
 * - openspec/changes/move-files-write-into-workflow-module/test-design.md:
 *   AC-2 gitignore 过滤接入（命中路径不入清单、未忽略路径透明通过、全无
 *   .gitignore 行为不变且 hook 不阻塞、fail-open）；AC-4 归账管线内移后的
 *   持久化观察点改造（净状态以临时项目内真实 workflow.json 为准——管线内部
 *   IO 不再经 workflow barrel，barrel mock 不再截获）
 *
 * Mock 面（进程边界）: node:fs.readFileSync 按参数分流（fd 0 返回事件 JSON、
 * 字符串路径转发真实读取，供管线装载 .gitignore / workflow.json）、
 * ./lib/session-registry、./lib/config、./commands/run-static-analysis、
 * process.stderr.write / process.exit / process.stdout.write spy。
 * 模块间调用不 mock。
 */

import * as NodeFs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';
import { fileURLToPath } from 'node:url';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import type * as ProjectRoot from './lib/project-root';

// ---------------------------------------------------------------------------
// 可控制 mock
// ---------------------------------------------------------------------------

// vi.hoisted 确保 mock 函数在 vi.mock 工厂被 hoist 之前就已初始化，避免 TDZ 错误
const {
  mockReadFileSync,
  mockReadConfig,
  mockRunStaticAnalysis,
  mockGetProjectDir,
  actualGetProjectDirRef,
  realReadFileSyncRef,
  mockBindSession,
  mockLookupChange,
  mockRunSweepPhase,
} = vi.hoisted(() => ({
  mockReadFileSync: vi.fn(),
  mockReadConfig: vi.fn(),
  mockRunStaticAnalysis: vi.fn(),
  mockGetProjectDir: vi.fn(),
  actualGetProjectDirRef: { current: null as null | (() => string) },
  realReadFileSyncRef: { current: null as null | ((...args: unknown[]) => string) },
  mockBindSession: vi.fn(),
  mockLookupChange: vi.fn(),
  mockRunSweepPhase: vi.fn(),
}));

// vi.mock 被提升到文件顶部，在静态 import 之前执行
vi.mock('node:fs', async (importOriginal) => {
  const actual: Record<string, unknown> = await importOriginal();
  // 捕获真实 readFileSync：stdin 分流时转发字符串路径（.gitignore / workflow.json 装载）
  realReadFileSyncRef.current = actual.readFileSync as (...args: unknown[]) => string;
  return { ...actual, readFileSync: mockReadFileSync };
});

vi.mock('./lib/config', () => ({
  readConfig: mockReadConfig,
}));

vi.mock('./lib/session-registry', () => ({
  bindSession: mockBindSession,
  lookupChange: mockLookupChange,
}));

vi.mock('./commands/run-static-analysis', () => ({
  runStaticAnalysis: mockRunStaticAnalysis,
}));

vi.mock('./commands/sweep-phase', () => ({
  runSweepPhase: mockRunSweepPhase,
}));

vi.mock('./lib/project-root', async (importOriginal) => {
  const actual = await importOriginal<typeof ProjectRoot>();
  actualGetProjectDirRef.current = actual.getProjectDir;
  mockGetProjectDir.mockImplementation(() => actual.getProjectDir());
  return {
    ...actual,
    getProjectDir: () => mockGetProjectDir() as string,
  };
});

// 在 hooks 模块加载前设置 process 拦截，防止模块顶层 main() 自动执行导致进程退出
const exitMock = vi.spyOn(process, 'exit').mockImplementation(() => undefined as never);
vi.spyOn(process.stderr, 'write').mockImplementation(() => true);

// 动态 import — vi.mock 已生效，process 拦截已就位
const { main, runProtectFiles, runRecordFiles, runSweepPhase, runStaticCheck, captureStderr } =
  await import('./hooks');

// 模块加载完成后设置 stdout spy（auto-execution 未写 stdout）
const stdoutWriteMock = vi.spyOn(process.stdout, 'write').mockImplementation(() => true);

// ---------------------------------------------------------------------------
// 辅助函数
// ---------------------------------------------------------------------------

/** 重置所有 mock 并设置默认行为 */
function resetMocks(): void {
  mockReadFileSync.mockReset();
  mockReadConfig.mockReset().mockReturnValue({ schema: 'spec-driven' });
  mockRunStaticAnalysis.mockReset().mockReturnValue(0);
  mockGetProjectDir.mockReset();
  if (actualGetProjectDirRef.current) {
    mockGetProjectDir.mockImplementation(() => actualGetProjectDirRef.current!());
  }
  mockBindSession.mockReset();
  mockLookupChange.mockReset();
  mockRunSweepPhase.mockReset();
  exitMock.mockClear();
  stdoutWriteMock.mockClear();
}

/**
 * record-files 场景的 stdin 分流：fd 0 返回事件 JSON；字符串路径转发真实
 * readFileSync——归账管线经 node:fs 读 .gitignore 与 workflow.json（缺失抛
 * ENOENT → 该层无规则），分流避免过滤器读到事件 JSON 文本。
 */
function stubRecordStdin(event: Record<string, unknown>): void {
  mockReadFileSync.mockImplementation((...args: unknown[]) => {
    if (args[0] === 0) return JSON.stringify(event);
    return realReadFileSyncRef.current?.(args[0], args[1]);
  });
}

/** 门②默认开启的运行态（gate 3 归一匹配 implement executor 用）。 */
const RECORD_ACTIVE_PHASE = {
  phase: 'implement',
  attempt: 1,
  start_at: '2026-09-18T08:00:00.000Z',
};

/** 在临时项目内创建 change 目录与合法 workflow.json（真盘 fixture），返回 changeDir。 */
function createRecordChangeFixture(
  root: string,
  files: { written: string[]; deleted?: string[] },
  changeName = 'change-a',
  options: { activePhase?: Record<string, unknown> | null } = {},
): string {
  const changeDir = path.join(root, 'openspec', 'changes', changeName);
  NodeFs.mkdirSync(changeDir, { recursive: true });
  const at = '2026-09-18T00:00:00.000Z';
  const fileLog = [
    ...files.written.map((p) => ({ op: 'write', scope: 'workflow', path: p, at })),
    ...(files.deleted ?? []).map((p) => ({ op: 'delete', scope: 'workflow', path: p, at })),
  ];
  NodeFs.writeFileSync(
    path.join(changeDir, 'workflow.json'),
    `${JSON.stringify(
      {
        workflow_type: 'requirement',
        created: '2026-09-18',
        eval: [],
        unknown_key: { keep: true },
        active_phase: options.activePhase === undefined ? RECORD_ACTIVE_PHASE : options.activePhase,
        file_log: fileLog,
      },
      null,
      2,
    )}\n`,
    'utf-8',
  );
  return changeDir;
}

/** 经真实 readFileSync 读回磁盘 workflow.json 原文（绕开 stdin 分流 mock 面）。 */
function readRecordWorkflowRaw(changeDir: string): string {
  const read = realReadFileSyncRef.current;
  if (!read) throw new Error('真实 readFileSync 未就绪（node:fs mock 工厂未执行）');
  return read(path.join(changeDir, 'workflow.json'), 'utf-8');
}

/**
 * 读回临时项目内真实 workflow.json 的 file_log 派生净状态。
 * （记录管线写 file_log 条目；观察点按 deriveNetState 语义在测试内重放。）
 */
function readRecordedFiles(changeDir: string): { written: string[]; deleted: string[] } {
  const { written, deleted } = readRecordLog(changeDir).reduce(
    (acc, entry) => {
      if (entry.op === 'write') {
        acc.deleted.delete(entry.path);
        acc.written.add(entry.path);
      } else if (entry.op === 'delete') {
        acc.written.delete(entry.path);
        acc.deleted.add(entry.path);
      } else {
        acc.written.delete(entry.path);
        acc.deleted.delete(entry.path);
      }
      return acc;
    },
    { written: new Set<string>(), deleted: new Set<string>() },
  );
  return { written: Array.from(written), deleted: Array.from(deleted) };
}

/** 读回盘上 file_log 原始条目（scope/attempt 断言用）。 */
function readRecordLog(
  changeDir: string,
): Array<{ op: string; scope: string; attempt?: number; path: string; at: string }> {
  const doc = JSON.parse(readRecordWorkflowRaw(changeDir)) as {
    file_log?: Array<{ op: string; scope: string; attempt?: number; path: string; at: string }>;
  };
  return doc.file_log ?? [];
}

/** 从 stdout spy calls 中提取最后写入的字符串 */
function getLastStdout(): string {
  return String(stdoutWriteMock.mock.lastCall?.[0] ?? '');
}

// ============================================================================
// hooks 子命令调度 — AC-1
// ============================================================================

describe('hooks 子命令调度 (AC-1)', () => {
  beforeEach(() => {
    resetMocks();
    mockReadFileSync.mockReturnValue(
      JSON.stringify({
        tool_name: 'Write',
        tool_input: { file_path: 'unprotected/file.txt' },
      }),
    );
  });

  it('process.argv[2] = "protect-files" 时 main 调用 runProtectFiles 并输出 allow JSON', () => {
    const origArgv = process.argv;
    process.argv = ['node', 'hooks.ts', 'protect-files'];
    try {
      main();
      const output = getLastStdout();
      const parsed = JSON.parse(output);
      expect(parsed).toHaveProperty('hookSpecificOutput');
    } finally {
      process.argv = origArgv;
    }
  });

  it('process.argv[2] = "static-check" 时 main 调用 runStaticCheck 并输出 JSON', () => {
    const origArgv = process.argv;
    process.argv = ['node', 'hooks.ts', 'static-check'];
    try {
      mockReadFileSync.mockReturnValue(JSON.stringify({ workspace_roots: ['/test'] }));
      main();
      const output = getLastStdout().trim();
      expect(output).toContain('{}');
    } finally {
      process.argv = origArgv;
    }
  });

  it('runProtectFiles 输出格式为 { hookSpecificOutput: { hookEventName, permissionDecision } }', () => {
    mockReadFileSync.mockReturnValue(
      JSON.stringify({
        tool_name: 'Write',
        tool_input: { file_path: 'openspec/config.json' },
      }),
    );
    runProtectFiles();
    const output = getLastStdout();
    const parsed = JSON.parse(output);
    expect(parsed).toEqual({
      hookSpecificOutput: {
        hookEventName: 'PreToolUse',
        permissionDecision: 'deny',
        permissionDecisionReason: expect.any(String),
      },
    });
  });

  it('未知子命令 "unknown" 时 process.exit(1)，stderr 含子命令名', () => {
    const origArgv = process.argv;
    process.argv = ['node', 'hooks.ts', 'unknown'];
    // 使用 dedicated spy 避免与 captureStderr 干扰
    const stderrSpy = vi.spyOn(process.stderr, 'write').mockImplementation(() => true);
    try {
      main();
      expect(exitMock).toHaveBeenCalledWith(1);
      expect(stderrSpy).toHaveBeenCalledWith(expect.stringContaining('Unknown subcommand'));
    } finally {
      stderrSpy.mockRestore();
      process.argv = origArgv;
    }
  });

  it('process.argv[2] 未定义时 process.exit(1)', () => {
    const origArgv = process.argv;
    process.argv = ['node', 'hooks.ts'];
    try {
      main();
      expect(exitMock).toHaveBeenCalledWith(1);
    } finally {
      process.argv = origArgv;
    }
  });

  it('process.argv[2]="" 空字符串时 process.exit(1) (边界)', () => {
    const origArgv = process.argv;
    process.argv = ['node', 'hooks.ts', ''];
    try {
      main();
      expect(exitMock).toHaveBeenCalledWith(1);
    } finally {
      process.argv = origArgv;
    }
  });

  it('顶层 try-catch 包裹整个处理流程，任何未捕获异常输出 { decision: "block", reason } (边界)', async () => {
    const origArgv = process.argv;
    process.argv = ['node', 'hooks.ts', 'protect-files'];

    // 让 mockReadFileSync 抛出异常，模拟未捕获异常传播到顶层 try-catch
    mockReadFileSync.mockImplementation(() => {
      throw new Error('模拟未捕获异常');
    });

    // 清除之前 stdout spy 的调用记录
    stdoutWriteMock.mockClear();

    // 重置模块缓存，强制 hooks.ts 重新执行模块级代码（即 try-catch 包裹的 main()）
    vi.resetModules();

    try {
      // 重新导入 — 模块级 main() 执行时 runProtectFiles 内部抛出异常，
      // 被 try-catch 捕获后输出 { decision: "block", reason }
      await import('./hooks');

      // 验证输出
      const output = String(stdoutWriteMock.mock.calls[0]?.[0] ?? '');
      const parsed = JSON.parse(output);
      expect(parsed.decision).toBe('block');
      expect(parsed.reason).toContain('模拟未捕获异常');
    } finally {
      process.argv = origArgv;
      mockReadFileSync.mockReset();
      stdoutWriteMock.mockClear();
    }
  });

  it('顶层 try-catch 捕获非 Error 对象（如字符串）时 String(error) 输出 { decision: "block", reason } (边界)', async () => {
    const origArgv = process.argv;
    process.argv = ['node', 'hooks.ts', 'protect-files'];
    mockReadFileSync.mockImplementation(() => {
      throw '字符串异常';
    });
    stdoutWriteMock.mockClear();
    vi.resetModules();
    try {
      await import('./hooks');
      const output = String(stdoutWriteMock.mock.calls[0]?.[0] ?? '');
      const parsed = JSON.parse(output);
      expect(parsed.decision).toBe('block');
      expect(parsed.reason).toContain('字符串异常');
    } finally {
      process.argv = origArgv;
      mockReadFileSync.mockReset();
      stdoutWriteMock.mockClear();
    }
  });
});

// ============================================================================
// protect-files 功能等价迁移 — AC-2
// ============================================================================

describe('protect-files 功能等价迁移 (AC-2)', () => {
  beforeEach(() => {
    resetMocks();
    mockReadConfig.mockReturnValue({ schema: 'spec-driven' });
  });

  // ---- Write / Edit 路径保护 ----

  it('parseInput 解析 Write 受保护文件路径返回 deny', () => {
    mockReadFileSync.mockReturnValue(
      JSON.stringify({
        tool_name: 'Write',
        tool_input: { file_path: 'openspec/config.json' },
      }),
    );
    runProtectFiles();
    const parsed = JSON.parse(getLastStdout());
    expect(parsed.hookSpecificOutput.permissionDecision).toBe('deny');
  });

  it('parseInput 解析 Edit 受保护文件路径返回 deny', () => {
    mockReadFileSync.mockReturnValue(
      JSON.stringify({
        tool_name: 'Edit',
        tool_input: { file_path: 'openspec/changes/my-feature/workflow.json' },
      }),
    );
    runProtectFiles();
    const parsed = JSON.parse(getLastStdout());
    expect(parsed.hookSpecificOutput.permissionDecision).toBe('deny');
  });

  it('parseInput 解析 Write 未受保护文件路径返回 allow', () => {
    mockReadFileSync.mockReturnValue(
      JSON.stringify({
        tool_name: 'Write',
        tool_input: { file_path: 'src/helper.ts' },
      }),
    );
    runProtectFiles();
    const parsed = JSON.parse(getLastStdout());
    expect(parsed.hookSpecificOutput.permissionDecision).toBe('allow');
  });

  // ---- Bash 写入检测 ----

  it('detectBashWrite — > 重定向到 workflow.json 返回 deny', () => {
    mockReadFileSync.mockReturnValue(
      JSON.stringify({
        tool_name: 'Bash',
        tool_input: { command: 'echo "[]" > openspec/changes/test/workflow.json' },
      }),
    );
    runProtectFiles();
    const parsed = JSON.parse(getLastStdout());
    expect(parsed.hookSpecificOutput.permissionDecision).toBe('deny');
  });

  it('detectBashWrite — >> 追加到 workflow.json 返回 deny', () => {
    mockReadFileSync.mockReturnValue(
      JSON.stringify({
        tool_name: 'Bash',
        tool_input: { command: 'echo "x" >> openspec/changes/test/workflow.json' },
      }),
    );
    runProtectFiles();
    const parsed = JSON.parse(getLastStdout());
    expect(parsed.hookSpecificOutput.permissionDecision).toBe('deny');
  });

  it('detectBashWrite — tee 写入 workflow.json 返回 deny', () => {
    mockReadFileSync.mockReturnValue(
      JSON.stringify({
        tool_name: 'Bash',
        tool_input: { command: "echo '[]' | tee openspec/changes/test/workflow.json" },
      }),
    );
    runProtectFiles();
    const parsed = JSON.parse(getLastStdout());
    expect(parsed.hookSpecificOutput.permissionDecision).toBe('deny');
  });

