      expect(exitMock).not.toHaveBeenCalled();
      expect(stdoutWriteMock).not.toHaveBeenCalled();
      expect(getCaptured()).toContain('record-files:');
      expect(getCaptured()).toContain('解析失败');
    } finally {
      restore();
    }
  });
});

