/**
 * 集成测试: 同一非法 workflow.json → 严格方抛错 / 容错方不崩溃
 *
 * 本关系验证「一个非法文件、两种失败语义」的跨模块契约：读 / 写关键路径必须硬失败
 * 并给出可操作指引，而列表路径必须软失败以保持 change 可见。集成测试在同一个真实
 * 临时 change 目录上，对同一份缺失 / 非法的 `workflow.json` 依次调用各入口，断言
 * 彼此不矛盾。
 *
 * 涉及模块:
 * - `plugins/dev-team/bin/src/lib/change-config.ts` — 严格类型读取
 * - `plugins/dev-team/bin/src/commands/phase-next.ts` — 严格消费者
 * - `plugins/dev-team/bin/src/commands/backtrack.ts` — 严格消费者
 * - `plugins/dev-team/bin/src/lib/eval-json.ts` — 写入前置校验
 * - `plugins/dev-team/bin/src/commands/change-list.ts` — 容错消费者
 *
 * 关联 AC: AC-13, AC-14
 */

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import { runBacktrack } from '../../src/commands/backtrack';
import { runChangeList } from '../../src/commands/change-list';
import { runPhaseLog } from '../../src/commands/phase-log';
import { runPhaseNext } from '../../src/commands/phase-next';
import { getProjectDir } from '../../src/lib/project-root';

// `getWorkflowType()` 经 `getProjectDir()` 解析工程根，优先级为 call-scoped →
// `CLAUDE_PROJECT_DIR` → `WORKSPACE_FOLDER_PATHS` → `process.cwd()`。这里把
// `getProjectDir` mock 成临时工程根，替代 `process.chdir`：Stryker 的 vitest runner
// 强制 worker 线程池，worker 中 `process.chdir` 会抛
// ERR_WORKER_UNSUPPORTED_OPERATION（与 run-static-analysis.test.ts 相同的处理）。
// 环境变量隔离仍然保留：被测命令之外的真实工程根不得介入。
vi.mock('../../src/lib/project-root');

const CHANGE = 'strict-workflow';
const RUN_ID = 'strict-run';

const ENV_KEYS = ['CLAUDE_PROJECT_DIR', 'WORKSPACE_FOLDER_PATHS'] as const;

function saveProjectEnv(): Record<(typeof ENV_KEYS)[number], string | undefined> {
  return {
    CLAUDE_PROJECT_DIR: process.env.CLAUDE_PROJECT_DIR,
    WORKSPACE_FOLDER_PATHS: process.env.WORKSPACE_FOLDER_PATHS,
  };
}

function restoreProjectEnv(saved: ReturnType<typeof saveProjectEnv>): void {
  for (const key of ENV_KEYS) {
    if (saved[key] === undefined) {
      delete process.env[key];
    } else {
      process.env[key] = saved[key];
    }
  }
}

let projectRoot: string;
let changeDir: string;
let savedProjectEnv: ReturnType<typeof saveProjectEnv>;

beforeEach(() => {
  savedProjectEnv = saveProjectEnv();
  delete process.env.CLAUDE_PROJECT_DIR;
  delete process.env.WORKSPACE_FOLDER_PATHS;
  projectRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'eval-strict-'));
  changeDir = path.join(projectRoot, 'openspec', 'changes', CHANGE);
  fs.mkdirSync(changeDir, { recursive: true });
  vi.mocked(getProjectDir).mockReturnValue(projectRoot);
});

afterEach(() => {
  restoreProjectEnv(savedProjectEnv);
  fs.rmSync(projectRoot, { recursive: true, force: true });
});

function writeRawWorkflow(raw: string): void {
  fs.writeFileSync(path.join(changeDir, 'workflow.json'), raw, 'utf-8');
}

function snapshotDir(): Record<string, string> {
  const snapshot: Record<string, string> = {};
  for (const name of fs.readdirSync(changeDir).sort()) {
    snapshot[name] = fs.readFileSync(path.join(changeDir, name), 'utf-8');
  }
  return snapshot;
}

function expectPhaseNext(): Error {
  try {
    runPhaseNext({ change: CHANGE, project_root: projectRoot, run_id: RUN_ID });
  } catch (e: unknown) {
    return e as Error;
  }
  throw new Error('expected runPhaseNext to throw, but it returned normally');
}

function expectBacktrack(): Error {
  try {
    runBacktrack({
      project_root: projectRoot,
      change: CHANGE,
      phase: 'proposal',
      backtrack_to: 'proposal',
      backtrack_reason: 'r',
    });
  } catch (e: unknown) {
    return e as Error;
  }
  throw new Error('expected runBacktrack to throw, but it returned normally');
}

function expectPhaseLog(): Error {
  try {
    runPhaseLog({
      project_root: projectRoot,
      change: CHANGE,
      phase: 'proposal',
      report: 'ok',
      checklist: [{ item: 'x', pass: true, evidence: 'ok' }],
    });
  } catch (e: unknown) {
    return e as Error;
  }
  throw new Error('expected runPhaseLog to throw, but it returned normally');
}

/** 容错方：始终返回结果而非抛错。 */
function changeEntry(): ReturnType<typeof runChangeList>['changes'][number] {
  const entry = runChangeList(projectRoot).changes.find((c) => c.name === CHANGE);
  expect(entry).toBeDefined();
  return entry!;
}

// ---------------------------------------------------------------------------
// 场景: workflow.json 缺失
// ---------------------------------------------------------------------------

describe('workflow.json 缺失', () => {
  it('runChangeList 仍列出该 change，workflow_done 为 false、latest_phase 为 null（AC-13 容错面）', () => {
    const entry = changeEntry();

    expect(entry.workflow_done).toBe(false);
    expect(entry.latest_phase).toBeNull();
  });

  it('runPhaseNext 抛错，message 含绝对路径与 change_create 指引，不返回 proposal（AC-13）', () => {
    const error = expectPhaseNext();

    expect(error.message).toContain('workflow.json 不存在');
    expect(error.message).toContain(path.join(changeDir, 'workflow.json'));
    expect(error.message).toContain('change_create');
  });

  it('runBacktrack 抛错，message 含绝对路径与 change_create 指引（AC-13）', () => {
    const error = expectBacktrack();

    expect(error.message).toContain('workflow.json 不存在');
    expect(error.message).toContain(path.join(changeDir, 'workflow.json'));
    expect(error.message).toContain('change_create');
  });

  it('runPhaseLog 抛错（workflow.json 缺失在前置读取处暴露），且目录内未新增 workflow.json / eval.json / 子目录（AC-13）', () => {
    const before = snapshotDir();

    const error = expectPhaseLog();

    expect(error.message).toContain('workflow.json 不存在');
    expect(error.message).toContain('change_create');
    expect(snapshotDir()).toEqual(before);
    expect(fs.readdirSync(changeDir)).toEqual([]);
  });

  it('四次调用后目录内容与调用前完全一致（严格方只读失败，无副作用）', () => {
    const before = snapshotDir();

    changeEntry();
    expectPhaseNext();
    expectBacktrack();
    expectPhaseLog();

    expect(snapshotDir()).toEqual(before);
  });
});

// ---------------------------------------------------------------------------
// 场景: workflow.json 格式非法
// ---------------------------------------------------------------------------

describe('workflow.json 格式非法', () => {
  const invalidDocuments: Record<string, string> = {
    '非法 JSON': '{ "workflow_type": "requirement" ',
    根为数组: JSON.stringify([{ phase: 'proposal', verdict: 'pass' }]),
    '根为 null': JSON.stringify(null),
    '缺 workflow_type': JSON.stringify({ created: '2026-09-11' }),
    'workflow_type 非枚举': JSON.stringify({ workflow_type: 'unknown-flow' }),
    'created 非 YYYY-MM-DD': JSON.stringify({
      workflow_type: 'requirement',
      created: '2026/09/11',
    }),
    'eval 为对象': JSON.stringify({ workflow_type: 'requirement', eval: {} }),
  };

  it('非法 JSON / 根为数组时 runPhaseNext、runBacktrack 抛错；磁盘文件内容未被改写（AC-14）', () => {
    for (const key of ['非法 JSON', '根为数组']) {
      writeRawWorkflow(invalidDocuments[key]);
      const before = fs.readFileSync(path.join(changeDir, 'workflow.json'), 'utf-8');

      expectPhaseNext();
      expectBacktrack();
      expect(fs.readFileSync(path.join(changeDir, 'workflow.json'), 'utf-8')).toBe(before);
    }
  });

  it('workflow_type 缺失 / 非枚举时抛错，message 含字段路径 workflow_type（AC-14）', () => {
    for (const key of ['缺 workflow_type', 'workflow_type 非枚举']) {
      writeRawWorkflow(invalidDocuments[key]);

      expect(expectPhaseNext().message).toContain('workflow_type');
      expect(expectBacktrack().message).toContain('workflow_type');
    }
  });

  it('created 非 YYYY-MM-DD 时抛错（AC-14）', () => {
    writeRawWorkflow(invalidDocuments['created 非 YYYY-MM-DD']);

    expect(expectPhaseNext().message).toContain('created');
    expect(expectBacktrack().message).toContain('created');
  });

  it('eval 为对象时 runPhaseLog 抛错且不把 eval 改写成合法数组（AC-12、AC-14）', () => {
    writeRawWorkflow(invalidDocuments['eval 为对象']);
    const before = fs.readFileSync(path.join(changeDir, 'workflow.json'), 'utf-8');

    const error = expectPhaseLog();

    expect(error.message).toContain('读取 workflow.json 失败');
    const doc = JSON.parse(
      fs.readFileSync(path.join(changeDir, 'workflow.json'), 'utf-8'),
    ) as Record<string, unknown>;
    expect(doc.eval).toEqual({});
    expect(fs.readFileSync(path.join(changeDir, 'workflow.json'), 'utf-8')).toBe(before);
  });

  it('根为 null / 缺 workflow_type 时 runPhaseLog 亦失败且不改写磁盘', () => {
    for (const key of ['根为 null', '缺 workflow_type']) {
      writeRawWorkflow(invalidDocuments[key]);
      const before = fs.readFileSync(path.join(changeDir, 'workflow.json'), 'utf-8');

      expectPhaseLog();
      expect(fs.readFileSync(path.join(changeDir, 'workflow.json'), 'utf-8')).toBe(before);
    }
  });

  it('同一非法文件下 runChangeList 均返回 workflow_done===false、latest_phase===null，change 仍出现（AC-14 容错面）', () => {
    for (const raw of Object.values(invalidDocuments)) {
      writeRawWorkflow(raw);

      let entry: ReturnType<typeof runChangeList>['changes'][number] | undefined;
      expect(() => {
        entry = runChangeList(projectRoot).changes.find((c) => c.name === CHANGE);
      }).not.toThrow();

      expect(entry).toBeDefined();
      expect(entry!.workflow_done).toBe(false);
      expect(entry!.latest_phase).toBeNull();
    }
  });

  it('非法 / 缺字段时不再按缺省 requirement 继续推进工作流（DEFAULT_WORKFLOW_TYPE 兜底语义已废弃）', () => {
    writeRawWorkflow(invalidDocuments['缺 workflow_type']);

    let result: ReturnType<typeof runPhaseNext> | null = null;
    try {
      result = runPhaseNext({ change: CHANGE, project_root: projectRoot, run_id: RUN_ID });
    } catch {
      result = null;
    }

    // 严格化后不允许返回任何 phase（尤其不得以 requirement 表返回 proposal）
    expect(result).toBeNull();
  });
});

bin/__tests__/eval-store-read-priority/e.source:
/**
 * 集成测试: readEvalJson 优先级 → phase_next / change_list
 *
 * `phase_next` 与 `change_list` 都只通过 `readEvalJson` 取条目，自身不得迁移或
 * 删除文件。本套件用真实磁盘组合「仅遗留文件 / 权威空数组 + 遗留非空 / 权威非数组 /
 * 两文件皆无」验证只读行为与列表字段。
 *
 * 涉及模块:
 * - `plugins/dev-team/bin/src/lib/eval-json.ts` — 读取优先级与校验
 * - `plugins/dev-team/bin/src/commands/phase-next.ts` — 只读消费者
 * - `plugins/dev-team/bin/src/commands/change-list.ts` — 只读消费者
 *
 * 关联 AC: AC-3, AC-5, AC-7, AC-12
 */

import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import { runChangeList } from '../../src/commands/change-list';
import { runPhaseNext } from '../../src/commands/phase-next';
import { type EvalEntry } from '../../src/lib/eval-json';
import { getProjectDir } from '../../src/lib/project-root';

// `getWorkflowType()` 经 `getProjectDir()` 解析工程根，优先级为 call-scoped →
// `CLAUDE_PROJECT_DIR` → `WORKSPACE_FOLDER_PATHS` → `process.cwd()`。这里把
// `getProjectDir` mock 成临时工程根，替代 `process.chdir`：Stryker 的 vitest runner
// 强制 worker 线程池，worker 中 `process.chdir` 会抛
// ERR_WORKER_UNSUPPORTED_OPERATION（与 run-static-analysis.test.ts 相同的处理）。
// 环境变量隔离仍然保留：被测命令之外的真实工程根不得介入。
vi.mock('../../src/lib/project-root');

const CHANGE = 'read-priority';
const RUN_ID = 'priority-run';

const ENV_KEYS = ['CLAUDE_PROJECT_DIR', 'WORKSPACE_FOLDER_PATHS'] as const;

function saveProjectEnv(): Record<(typeof ENV_KEYS)[number], string | undefined> {
  return {
    CLAUDE_PROJECT_DIR: process.env.CLAUDE_PROJECT_DIR,
    WORKSPACE_FOLDER_PATHS: process.env.WORKSPACE_FOLDER_PATHS,
  };
}

function restoreProjectEnv(saved: ReturnType<typeof saveProjectEnv>): void {
  for (const key of ENV_KEYS) {
    if (saved[key] === undefined) {
      delete process.env[key];
    } else {
      process.env[key] = saved[key];
    }
  }
}

let projectRoot: string;
let changeDir: string;
let savedProjectEnv: ReturnType<typeof saveProjectEnv>;

beforeEach(() => {
  savedProjectEnv = saveProjectEnv();
  delete process.env.CLAUDE_PROJECT_DIR;
  delete process.env.WORKSPACE_FOLDER_PATHS;
  projectRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'eval-priority-'));
  changeDir = path.join(projectRoot, 'openspec', 'changes', CHANGE);
  fs.mkdirSync(changeDir, { recursive: true });
  vi.mocked(getProjectDir).mockReturnValue(projectRoot);
});

afterEach(() => {
  restoreProjectEnv(savedProjectEnv);
  fs.rmSync(projectRoot, { recursive: true, force: true });
});

function writeWorkflow(doc: unknown): void {
  fs.writeFileSync(path.join(changeDir, 'workflow.json'), JSON.stringify(doc, null, 2), 'utf-8');
}

function writeLegacy(entries: unknown): void {
  fs.writeFileSync(path.join(changeDir, 'eval.json'), JSON.stringify(entries), 'utf-8');
}

function makeEntry(
  overrides: Partial<EvalEntry> & Pick<EvalEntry, 'phase' | 'verdict'>,
): EvalEntry {
  return {
    attempt: 1,
    timestamp: '2026-09-11T10:00:00.000Z',
    report: 'r',
    checklist: [],
    backtrack_to: null,
    ...overrides,
  };
}

/** 快照 change 目录下所有文件的字节内容，用于断言只读。 */
function snapshotDir(): Record<string, string> {
  const snapshot: Record<string, string> = {};
  for (const name of fs.readdirSync(changeDir).sort()) {
    snapshot[name] = fs.readFileSync(path.join(changeDir, name), 'utf-8');
  }
  return snapshot;
}

function phaseNext(): ReturnType<typeof runPhaseNext> {
  return runPhaseNext({ change: CHANGE, project_root: projectRoot, run_id: RUN_ID });
}

function changeList(): ReturnType<typeof runChangeList> {
  return runChangeList(projectRoot);
}

function changeEntry(): ReturnType<typeof runChangeList>['changes'][number] {
  const entry = changeList().changes.find((c) => c.name === CHANGE);
  expect(entry).toBeDefined();
  return entry!;
}

// ---------------------------------------------------------------------------
// 场景: 仅遗留 eval.json 的只读兼容
// ---------------------------------------------------------------------------

describe('仅遗留 eval.json 的只读兼容', () => {
  beforeEach(() => {
    writeWorkflow({ workflow_type: 'requirement', created: '2026-09-11' });
  });

  it('phase_next 返回 dev-design 且不写盘（AC-3）', () => {
    writeLegacy([
      makeEntry({
        phase: 'proposal',
        verdict: 'pass',
        report: '提案通过',
        timestamp: '2026-09-11T09:00:00.000Z',
      }),
      makeEntry({
        phase: 'dev-design',
        verdict: 'fail',
        report: '设计待改进',
        timestamp: '2026-09-11T11:00:00.000Z',
      }),
    ]);
    const before = snapshotDir();

    const result = phaseNext();

    expect(result.next_phase).toBe('dev-design');
    expect(result.error).toBeNull();
    expect(result.last_result!.phase).toBe('dev-design');
    expect(snapshotDir()).toEqual(before);
  });

  it('change_list 填出 latest_phase 且 artifacts 无 eval.json（AC-7）', () => {
    writeLegacy([makeEntry({ phase: 'proposal', verdict: 'pass', report: '提案通过' })]);
    fs.writeFileSync(path.join(changeDir, 'proposal.md'), '# proposal', 'utf-8');
    const before = snapshotDir();

    const entry = changeEntry();

    expect(entry.latest_phase).toEqual({ phase: 'proposal', verdict: 'pass' });
    expect(entry.artifacts).toContain('proposal.md');
    expect(entry.artifacts).not.toContain('eval.json');
    expect(snapshotDir()).toEqual(before);
  });

  it('遗留根为对象时 phase_next 抛 Failed to read workflow.json（包装根类型错误），change_list 不抛且 workflow_done 为 false', () => {
    fs.writeFileSync(
      path.join(changeDir, 'eval.json'),
      JSON.stringify({ phase: 'proposal', verdict: 'pass' }),
      'utf-8',
    );

    expect(() => phaseNext()).toThrow(
      /Failed to read workflow\.json: .*eval\.json 根元素必须是数组/,
    );

    expect(() => changeList()).not.toThrow();
    expect(changeEntry().workflow_done).toBe(false);
  });

  it('两文件皆无评估来源时 phase_next 返回 first run proposal，change_list.latest_phase 为 null（AC-3）', () => {
    const result = phaseNext();

    expect(result.next_phase).toBe('proposal');
    expect(result.last_result).toBeNull();
    expect(changeEntry().latest_phase).toBeNull();
    expect(changeEntry().workflow_done).toBe(false);
  });
});

// ---------------------------------------------------------------------------
// 场景: 权威空数组忽略遗留文件
// ---------------------------------------------------------------------------

describe('权威空数组忽略遗留文件', () => {
  it('eval===[] 挡住遗留非空数组：phase_next 回到 first run（AC-5）', () => {
    writeWorkflow({ workflow_type: 'requirement', created: '2026-09-11', eval: [] });
    writeLegacy([
      makeEntry({ phase: 'proposal', verdict: 'pass' }),
      makeEntry({ phase: 'dev-design', verdict: 'pass' }),
      makeEntry({ phase: 'test-design', verdict: 'pass' }),
    ]);

    const result = phaseNext();

    expect(result.next_phase).toBe('proposal');
    expect(result.last_result).toBeNull();
    expect(changeEntry().latest_phase).toBeNull();
    expect(changeEntry().workflow_done).toBe(false);
  });

  it('phase_next 不 unlink 遗留 eval.json，两文件字节不变（AC-3）', () => {
    writeWorkflow({ workflow_type: 'requirement', created: '2026-09-11', eval: [] });
    writeLegacy([makeEntry({ phase: 'proposal', verdict: 'pass' })]);
    const before = snapshotDir();

    phaseNext();
    changeList();

    expect(snapshotDir()).toEqual(before);
    expect(fs.existsSync(path.join(changeDir, 'eval.json'))).toBe(true);
  });

  it('eval 为对象时 phase_next 抛错，change_list 该 change 仍在列表且 workflow_done 为 false（AC-12）', () => {
    writeWorkflow({ workflow_type: 'requirement', created: '2026-09-11', eval: {} });

    // 整文件校验（getWorkflowType）先于条目读取失败
    expect(() => phaseNext()).toThrow(/workflow\.json 格式非法/);

    expect(() => changeList()).not.toThrow();
    const entry = changeEntry();
    expect(entry.workflow_done).toBe(false);
    expect(entry.latest_phase).toBeNull();
  });

  it('eval===[] 且无遗留文件时与「无评估条目」相同', () => {
    writeWorkflow({ workflow_type: 'requirement', created: '2026-09-11', eval: [] });

    const result = phaseNext();

    expect(result.next_phase).toBe('proposal');
    expect(changeEntry().workflow_done).toBe(false);
    expect(changeEntry().latest_phase).toBeNull();
  });
});

bin/__tests__/eval-store-hook-vs-fs/eval.source:
/**
 * 集成测试: PreToolUse deny → Node fs 写 workflow.json
 *
 * Hook 与 MCP 不共享写入通道：agent 工具调用经 `runProtectFiles`，MCP 经 Node
 * `fs`。本套件对同一相对路径分别走 stdin Write 与 `writeEvalJson` /
 * `runChangeCreate`，证明 deny 不阻止进程内落盘；同时对 `eval.json` 断言
 * 「内置规则放行」与「MCP 侧迁移删除」并存，避免出现「agent 放行、MCP 却不再
 * 清理」的双源残留。
 *
 * 涉及模块:
 * - `plugins/dev-team/bin/src/hooks.ts` — PreToolUse 拦截
 * - `plugins/dev-team/bin/src/lib/eval-json.ts` — MCP 路径：进程内 fs 写
 * - `plugins/dev-team/bin/src/commands/change-create.ts` — MCP 路径：创建
 *
 * 关联 AC: AC-8, AC-9
 */

import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

import { afterEach, beforeEach, describe, expect, it, vi } from 'vite-plus/test';

import { getProjectDir } from '../../src/lib/project-root';

// ---------------------------------------------------------------------------
// hook stdin / stdout harness
// ---------------------------------------------------------------------------

const { stdinRef, mockReadConfig } = vi.hoisted(() => ({
  stdinRef: { current: '' },
  mockReadConfig: vi.fn(),
}));

// 只替换 fd 0（stdin）的读取；路径读取委托给真实实现，保证 eval-json 的落盘不受影响。
vi.mock('node:fs', async (importOriginal) => {
  const actual = await importOriginal<typeof fs>();
  return {
    ...actual,
    readFileSync: ((...args: unknown[]) => {
      if (args[0] === 0) {
        return stdinRef.current;
      }
      return (actual.readFileSync as (...rest: unknown[]) => unknown)(...args);
    }) as typeof actual.readFileSync,
  };
});

vi.mock('../../src/lib/config', () => ({
  readConfig: mockReadConfig,
}));

// `runProtectFiles` → `loadPatterns(getProjectDir())` 需要工程根。这里把
// `getProjectDir` mock 成临时工程根，替代 `process.chdir`：Stryker 的 vitest runner
// 强制 worker 线程池，worker 中 `process.chdir` 会抛
// ERR_WORKER_UNSUPPORTED_OPERATION（与 run-static-analysis.test.ts 相同的处理）。
vi.mock('../../src/lib/project-root');

// 拦截进程退出，避免模块顶层 main() 因未知子命令终止测试进程
const exitMock = vi.spyOn(process, 'exit').mockImplementation(() => undefined as never);
vi.spyOn(process.stderr, 'write').mockImplementation(() => true);

const { runProtectFiles } = await import('../../src/hooks');
const { runChangeCreate } = await import('../../src/commands/change-create');
const { readEvalJson, writeEvalJson } = await import('../../src/lib/eval-json');

const stdoutWriteMock = vi.spyOn(process.stdout, 'write').mockImplementation(() => true);

// ---------------------------------------------------------------------------
// helpers
// ---------------------------------------------------------------------------

let projectRoot: string;
let changeDir: string;

type HookOutput = {
  hookSpecificOutput: { permissionDecision: string; permissionDecisionReason: string };
};

/** 通过 stdin 提交一次工具调用并返回解析后的 hook 输出。 */
function runHook(payload: Record<string, unknown>): HookOutput {
  stdinRef.current = JSON.stringify(payload);
  stdoutWriteMock.mockClear();
  runProtectFiles();
  return JSON.parse(String(stdoutWriteMock.mock.calls[0]?.[0] ?? '')) as HookOutput;
}

beforeEach(() => {
  projectRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'hook-vs-fs-'));
  changeDir = path.join(projectRoot, 'openspec', 'changes', 'demo');
  fs.mkdirSync(changeDir, { recursive: true });
  vi.mocked(getProjectDir).mockReturnValue(projectRoot);

  exitMock.mockClear();
  stdoutWriteMock.mockClear();
  mockReadConfig.mockReset().mockReturnValue({ schema: 'spec-driven' });
  stdinRef.current = '';
});

afterEach(() => {
  fs.rmSync(projectRoot, { recursive: true, force: true });
});

// ---------------------------------------------------------------------------
// 场景: 工具 deny 与 fs 成功并存
// ---------------------------------------------------------------------------

describe('工具 deny 与 fs 成功并存', () => {
  it('Write workflow.json 时 hook deny，同时 writeEvalJson 在临时 change 目录写成功（AC-8）', () => {
    fs.writeFileSync(
      path.join(changeDir, 'workflow.json'),
      JSON.stringify({ workflow_type: 'requirement', created: '2026-09-11' }),
      'utf-8',
    );

    const hookOutput = runHook({
      tool_name: 'Write',
      tool_input: { file_path: 'openspec/changes/demo/workflow.json' },
    });
    expect(hookOutput.hookSpecificOutput.permissionDecision).toBe('deny');
    expect(hookOutput.hookSpecificOutput.permissionDecisionReason).toContain('workflow.json');

    // 进程内 fs 不受 PreToolUse 限制
    writeEvalJson(changeDir, [
      {
        phase: 'proposal',
        verdict: 'pass',
        attempt: 1,
        timestamp: '2026-09-11T10:00:00.000Z',
        report: 'ok',
        checklist: [],
        backtrack_to: null,
      },
    ]);

    expect(readEvalJson(changeDir)).toHaveLength(1);
  });

  it('runChangeCreate 仍能写 workflow.json（进程内 fs 不受 hook 限制）（AC-8）', () => {
    const hookOutput = runHook({
      tool_name: 'Write',
      tool_input: { file_path: 'openspec/changes/brand-new/workflow.json' },
    });
    expect(hookOutput.hookSpecificOutput.permissionDecision).toBe('deny');

    const result = runChangeCreate('brand-new', projectRoot, 'test-only');

    const doc = JSON.parse(
      fs.readFileSync(path.join(result.path, 'workflow.json'), 'utf-8'),
    ) as Record<string, unknown>;
    expect(doc.workflow_type).toBe('test-only');
    expect(readEvalJson(result.path)).toEqual([]);
  });

  it('Shell 重定向写 workflow.json 时 deny，且不影响随后的 writeEvalJson', () => {
    fs.writeFileSync(
      path.join(changeDir, 'workflow.json'),
      JSON.stringify({ workflow_type: 'requirement', created: '2026-09-11' }),
      'utf-8',
    );

    const hookOutput = runHook({
      tool_name: 'Bash',
      tool_input: { command: 'echo "{}" > openspec/changes/demo/workflow.json' },
    });
    expect(hookOutput.hookSpecificOutput.permissionDecision).toBe('deny');

    expect(() =>
      writeEvalJson(changeDir, [
        {
          phase: 'dev-design',
          verdict: 'pass',
          attempt: 1,
          timestamp: '2026-09-11T10:00:00.000Z',
          report: 'ok',
          checklist: [],
          backtrack_to: null,
        },
      ]),
    ).not.toThrow();
    expect(readEvalJson(changeDir)).toHaveLength(1);
  });

  it('StrReplace workflow.json 时 deny，Edit 对照同样 deny', () => {
    for (const toolName of ['StrReplace', 'Edit']) {
      const hookOutput = runHook({
        tool_name: toolName,
        tool_input: { file_path: 'openspec/changes/demo/workflow.json' },
      });

      expect(hookOutput.hookSpecificOutput.permissionDecision).toBe('deny');
      expect(hookOutput.hookSpecificOutput.permissionDecisionReason).toContain(toolName);
    }
  });

  it('config.json 同批仍 deny（内置集合未整体放宽）（AC-8）', () => {
    const hookOutput = runHook({
      tool_name: 'Write',
      tool_input: { file_path: 'openspec/config.json' },
    });

    expect(hookOutput.hookSpecificOutput.permissionDecision).toBe('deny');
    expect(hookOutput.hookSpecificOutput.permissionDecisionReason).toContain(
      'openspec/config.json',
    );
  });
});

// ---------------------------------------------------------------------------
// 场景: eval.json 内置豁免与 MCP 迁移删除并存
// ---------------------------------------------------------------------------

describe('eval.json 内置豁免与 MCP 迁移删除并存', () => {
  beforeEach(() => {
    fs.writeFileSync(
      path.join(changeDir, 'workflow.json'),
      JSON.stringify({ workflow_type: 'requirement', created: '2026-09-11' }),
      'utf-8',
    );
  });

  it('无 write_protection 时 Write eval.json 不产生内置 deny（AC-9）', () => {
    const hookOutput = runHook({
      tool_name: 'Write',
      tool_input: { file_path: 'openspec/changes/demo/eval.json' },
    });

    expect(hookOutput.hookSpecificOutput.permissionDecision).not.toBe('deny');
    expect(hookOutput.hookSpecificOutput.permissionDecision).toBe('allow');
  });

  it('同一批次再 writeEvalJson 时遗留 eval.json 被删除，条目落在 workflow.json.eval（AC-4、AC-9）', () => {
    fs.writeFileSync(
      path.join(changeDir, 'eval.json'),
      JSON.stringify([
        {
          phase: 'proposal',
          verdict: 'pass',
          attempt: 1,
          timestamp: '2026-09-11T09:00:00.000Z',
          report: '遗留条目',
          checklist: [],
          backtrack_to: null,
        },
      ]),
      'utf-8',
    );

    const hookOutput = runHook({
      tool_name: 'Write',
      tool_input: { file_path: 'openspec/changes/demo/eval.json' },
    });
    expect(hookOutput.hookSpecificOutput.permissionDecision).not.toBe('deny');

    writeEvalJson(changeDir, [
      {
        phase: 'proposal',
        verdict: 'pass',
        attempt: 1,
        timestamp: '2026-09-11T10:00:00.000Z',
        report: '迁移后条目',
        checklist: [],
        backtrack_to: null,
      },
    ]);

    expect(fs.existsSync(path.join(changeDir, 'eval.json'))).toBe(false);
    const entries = readEvalJson(changeDir);
    expect(entries).toHaveLength(1);
    expect(entries[0].report).toBe('迁移后条目');
  });

  it('write_protection.files 显式加入 eval.json glob 后同一 stdin 变为 deny', () => {
    mockReadConfig.mockReturnValue({
      schema: 'spec-driven',
      write_protection: {
        files: [{ glob: 'openspec/changes/*/eval.json', reason: '用户保护：%s（%t）' }],
      },
    });

    const hookOutput = runHook({
      tool_name: 'Write',
      tool_input: { file_path: 'openspec/changes/demo/eval.json' },
    });

    expect(hookOutput.hookSpecificOutput.permissionDecision).toBe('deny');
    expect(hookOutput.hookSpecificOutput.permissionDecisionReason).toContain('用户保护');
  });
});

